/* @autogenerated */
package net.civeira.phylax.feature.oauth.client.domain;

/**
 * Client authentication methods an endpoint accepts.
 *
 * <p>
 * A client always uses one of its registered methods: the secret method of its
 * {@code tokenEndpointAuthMethod} and, when it allows public access, {@code none}.
 */
public enum ClientAuthPolicy {
  /**
   * Exactly a registered method, {@code none} included: authorization_code and refresh_token. A
   * client registered for client_secret_basic cannot send its secret in the body, and vice versa.
   */
  REGISTERED_METHOD,
  /**
   * Any secret method (Basic or body), never {@code none}: password, client_credentials, mfa, PAR,
   * introspection and revocation.
   */
  SECRET,
  /**
   * As {@link #SECRET}, and also the client_id alone of a client allowed public access: device
   * authorization and the device_code grant.
   */
  SECRET_OR_PUBLIC
}
